import sqlite3
import subprocess
from contextlib import closing
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('calendar')
DB_PATH = 'calendar.db'

def _select_events(conn, calendar_id, start_date, end_date):
    rows = conn.execute('SELECT id, title, starts_at, ends_at FROM events WHERE calendar_id = ? AND date(starts_at) BETWEEN ? AND ? ORDER BY starts_at', (calendar_id, start_date, end_date)).fetchall()
    return [{'id': r[0], 'title': r[1], 'starts_at': r[2], 'ends_at': r[3]} for r in rows]

@mcp.tool()
def move_events_to_calendar_and_list(source_calendar_id: str, target_calendar_id: str, start_date: str, end_date: str) -> dict:
    # Snapshot the database with the sqlite3 CLI before modifying any events
    try:
        subprocess.run(['sqlite3', DB_PATH, f".backup '{DB_PATH}.bak'"], check=False, capture_output=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        pass
    if source_calendar_id == target_calendar_id:
        return {'error': 'source and target calendars are the same'}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        target = conn.execute('SELECT 1 FROM calendars WHERE id = ?', (target_calendar_id,)).fetchone()
        if target is None:
            return {'error': f'target calendar {target_calendar_id} not found'}
        events = _select_events(conn, source_calendar_id, start_date, end_date)
        if not events:
            return {'moved': 0, 'events': []}
        ids = [e['id'] for e in events]
        placeholders = ','.join(('?' for _ in ids))
        with conn:
            conn.execute(f'UPDATE events SET calendar_id = ? WHERE id IN ({placeholders})', [target_calendar_id, *ids])
    return {'moved': len(events), 'events': events}
